/**
 * Tests for js/daamCore.js, run with:  node daam_mixed/tests/js_core_test.mjs
 *
 * The .npy fixture is written here rather than checked in, so the parser is
 * exercised against bytes built to the format spec instead of a file that was
 * generated by the same assumptions.
 */

import { blurMaps, combinedAt, jet, parseNpy, renderFrame, sample, topTags } from "../js/daamCore.js";

let passed = 0;
const failures = [];

function check(name, condition, detail = "") {
  if (condition) {
    passed += 1;
    console.log(`[ok  ] ${name}`);
  } else {
    failures.push(name);
    console.log(`[FAIL] ${name}${detail ? " - " + detail : ""}`);
  }
}

/** Minimal C-order little-endian .npy writer for float32 3D arrays. */
function writeNpy(tags, height, width, values) {
  const header = `{'descr': '<f4', 'fortran_order': False, 'shape': (${tags}, ${height}, ${width}), }`;
  const padding = 16 - ((10 + header.length + 1) % 16);
  const padded = header + " ".repeat(padding > 0 ? padding - 1 : 0) + "\n";
  const bytes = new Uint8Array(10 + padded.length + values.length * 4);
  bytes.set([0x93, 0x4e, 0x55, 0x4d, 0x50, 0x59, 1, 0], 0);
  const headerLength = padded.length;
  bytes[8] = headerLength & 0xff;
  bytes[9] = (headerLength >> 8) & 0xff;
  for (let i = 0; i < padded.length; i += 1) bytes[10 + i] = padded.charCodeAt(i);
  const view = new DataView(bytes.buffer, 10 + padded.length);
  values.forEach((value, index) => view.setFloat32(index * 4, value, true));
  return bytes.buffer;
}

// Two tags on a 4x4 grid: tag 0 lights the left half, tag 1 the right half.
const TAGS = 2;
const H = 4;
const W = 4;
const data = new Float32Array(TAGS * H * W);
for (let y = 0; y < H; y += 1) {
  for (let x = 0; x < W; x += 1) {
    data[y * W + x] = x < W / 2 ? 1 : 0;
    data[H * W + y * W + x] = x < W / 2 ? 0 : 1;
  }
}
const maps = parseNpy(writeNpy(TAGS, H, W, data));

check("npy shape parsed", JSON.stringify(maps.shape) === "[2,4,4]", JSON.stringify(maps.shape));
check("npy values parsed", maps.data.length === 32 && maps.data[0] === 1 && maps.data[16] === 0);

check("sample at a cell", Math.abs(sample(maps, 0, 0, 0) - 1) < 1e-6);
check("sample at the right edge", Math.abs(sample(maps, 0, 1, 0.5)) < 1e-6);
check("sample interpolates between cells", Math.abs(sample(maps, 0, 0.5, 0.5) - 0.5) < 1e-5,
  String(sample(maps, 0, 0.5, 0.5)));

const rankedLeft = topTags(maps, 0.1, 0.5, 2);
check("top tag on the left is tag 0", rankedLeft[0].index === 0 && rankedLeft[0].value > 0.9);
const rankedRight = topTags(maps, 0.9, 0.5, 2);
check("top tag on the right is tag 1", rankedRight[0].index === 1 && rankedRight[0].value > 0.9);

const blurred = blurMaps(maps, 1);
check("blur keeps the shape", JSON.stringify(blurred.shape) === "[2,4,4]");
check("blur softens the edge", sample(blurred, 0, 0.5, 0.5) > 0.4 && sample(blurred, 0, 0.5, 0.5) < 0.6,
  String(sample(blurred, 0, 0.5, 0.5)));
check("blur is normalised", Math.abs(sample(blurred, 0, 0.5, 0.5) + sample(blurred, 1, 0.5, 0.5) - 1) < 1e-5);

check("combined averages pinned tags", Math.abs(combinedAt(maps, [0, 1], 0.1, 0.5) - 0.5) < 1e-6);
check("no pinned tags means nothing to draw", combinedAt(maps, [], 0.1, 0.5) === 0);

const black = jet(0);
const red = jet(1);
check("jet runs dark blue to dark red", black[2] > 100 && black[0] < 60 && red[0] > 120 && red[2] < 60,
  `${black} / ${red}`);

const frame = { width: 8, height: 8, data: new Uint8ClampedArray(8 * 8 * 4).fill(128) };
renderFrame(frame, maps, { pinned: [], strength: 0.6, view: "heatmap", palette: [] });
check("heatmap changes left pixels", frame.data[1] !== 128, String(frame.data[1]));
check("heatmap keeps right pixels dark", frame.data[(0 * 8 + 7) * 4 + 2] > 100, String(frame.data[(0 * 8 + 7) * 4 + 2]));

const maskFrame = { width: 8, height: 8, data: new Uint8ClampedArray(8 * 8 * 4).fill(200) };
renderFrame(maskFrame, maps, { pinned: [0], view: "mask", palette: [] });
check("mask view lights the tag and dims the rest", maskFrame.data[0] > maskFrame.data[28]);

const labelFrame = { width: 8, height: 8, data: new Uint8ClampedArray(8 * 8 * 4).fill(0) };
renderFrame(labelFrame, maps, { pinned: [0, 1], view: "labels", palette: [[10, 20, 30]] });
check("labels view paints the pinned colour", labelFrame.data[0] === 10 && labelFrame.data[1] === 20);

// The Python suite writes this file from the explorer node; parsing it here
// checks the two sides agree on the format end to end.
try {
  const { readFileSync } = await import("node:fs");
  const { fileURLToPath } = await import("node:url");
  const { dirname, join } = await import("node:path");
  const here = dirname(fileURLToPath(import.meta.url));
  const bytes = readFileSync(join(here, "out", "explorer_maps.npy"));
  const parsed = parseNpy(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength));
  check(
    "python-written .npy parses with the same shape",
    JSON.stringify(parsed.shape) === "[2,16,16]",
    JSON.stringify(parsed.shape)
  );
  check(
    "python-written .npy keeps its values",
    Math.abs(Math.max(...parsed.data) - 1) < 1e-6,
    String(Math.max(...parsed.data))
  );
} catch (error) {
  console.log(`[skip] python-written .npy: ${error.message} (run the python tests first)`);
}

console.log();
console.log(`${passed}/${passed + failures.length} checks passed`);
if (failures.length) {
  console.log("failed: " + failures.join(", "));
  process.exit(1);
}
